package com.aistock.scheduler.alert;
import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;
import java.net.URI;import java.net.http.*;import java.time.Duration;import java.nio.ByteBuffer;import java.io.ByteArrayOutputStream;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;
import org.springframework.http.HttpStatus;
final class AlertTaskHttp {
 private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();private final String token;private final ObjectMapper mapper;
 AlertTaskHttp(String token,ObjectMapper mapper){this.token=token;this.mapper=mapper.copy().enable(com.fasterxml.jackson.core.JsonParser.Feature.STRICT_DUPLICATE_DETECTION).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);}
 JsonNode call(String base,String path,Object body,Duration timeout){if(token.isBlank()||base==null||base.isBlank())throw error("ALERT_DEPENDENCY_UNAVAILABLE");try{var builder=HttpRequest.newBuilder(URI.create(base).resolve(path)).timeout(timeout).header("X-Service-Token",token).header("Accept","application/json");if(body==null)builder.GET();else builder.header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body)));var subscriber=new Limited();var future=client.sendAsync(builder.build(),i->subscriber);try{var response=future.get(timeout.toMillis(),TimeUnit.MILLISECONDS);if(response.statusCode()>=300&&response.statusCode()<400)throw error("ALERT_DEPENDENCY_UNAVAILABLE");var n=mapper.readTree(response.body());if(n==null||!n.isObject())throw error("ALERT_DEPENDENCY_UNAVAILABLE");if(response.statusCode()!=200){String code=n.path("code").asText();throw new Remote(response.statusCode(),code.matches("[A-Z0-9_]{1,64}")?code:"ALERT_RECEIPT_INVALID");}return n;}finally{future.cancel(true);subscriber.cancel();}}catch(Remote e){throw e;}catch(InterruptedException e){Thread.currentThread().interrupt();throw error("ALERT_DEPENDENCY_UNAVAILABLE");}catch(Exception e){throw error("ALERT_DEPENDENCY_UNAVAILABLE");}}
 static Remote error(String c){return new Remote(-1,c);}
 static final class Remote extends RuntimeException {final int status;final String code;Remote(int status,String code){super("Alert dependency unavailable");this.status=status;this.code=code;}}
 private static final class Limited implements HttpResponse.BodySubscriber<byte[]> {
  private final ByteArrayOutputStream bytes=new ByteArrayOutputStream();private final CompletableFuture<byte[]> body=new CompletableFuture<>();private final AtomicReference<Flow.Subscription> subscription=new AtomicReference<>();
  public CompletionStage<byte[]> getBody(){return body;}public void onSubscribe(Flow.Subscription s){if(!subscription.compareAndSet(null,s)||body.isDone()){s.cancel();return;}s.request(1);}public void onNext(List<ByteBuffer> buffers){if(body.isDone())return;for(var b:buffers){if(b.remaining()>131072-bytes.size()){cancel();return;}var chunk=new byte[b.remaining()];b.get(chunk);bytes.writeBytes(chunk);}var s=subscription.get();if(s!=null&&!body.isDone())s.request(1);}public void onError(Throwable t){body.completeExceptionally(t);}public void onComplete(){body.complete(bytes.toByteArray());}void cancel(){var s=subscription.get();if(s!=null)s.cancel();body.completeExceptionally(new java.io.IOException("Alert body cancelled"));}
 }
}
